-- 熙心健康医生端数据库及演示数据（MySQL 8，UTF-8）。可重复执行，不清空已有表。
CREATE DATABASE IF NOT EXISTS health_check_system CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE health_check_system;
SET NAMES utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_patient (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(60) NOT NULL, sex VARCHAR(4) NOT NULL,
 age INT NOT NULL, phone VARCHAR(20) NOT NULL, identity_card VARCHAR(20) NOT NULL,
 health_status VARCHAR(10) NOT NULL DEFAULT '正常', tags VARCHAR(200) NOT NULL DEFAULT '无',
 last_exam_date DATE NULL, visit_count INT NOT NULL DEFAULT 1, follow_up TINYINT NOT NULL DEFAULT 0,
 address VARCHAR(255) NOT NULL DEFAULT '', notes TEXT, avatar VARCHAR(20) DEFAULT 'female',
 deleted TINYINT NOT NULL DEFAULT 0, created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 INDEX idx_patient_identity(identity_card), INDEX idx_patient_phone(phone), INDEX idx_patient_exam(last_exam_date)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_appointment (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, appointment_no VARCHAR(40) NOT NULL UNIQUE,
 exam_date DATE NOT NULL, time_slot VARCHAR(30) NOT NULL, package_name VARCHAR(80) NOT NULL,
 source VARCHAR(30) NOT NULL DEFAULT '微信小程序', status VARCHAR(15) NOT NULL DEFAULT '待确认',
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(patient_id) REFERENCES doctor_patient(id), INDEX idx_appointment_date(exam_date,status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_report_template (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL, category VARCHAR(30) NOT NULL,
 description VARCHAR(200) NOT NULL, advice TEXT NOT NULL, items JSON NOT NULL,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_report (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, report_no VARCHAR(40) NOT NULL UNIQUE,
 exam_date DATE NOT NULL, package_name VARCHAR(80) NOT NULL, status VARCHAR(15) NOT NULL DEFAULT '草稿',
 score INT NOT NULL DEFAULT 95, conclusion TEXT NOT NULL, advice TEXT NOT NULL, items JSON NOT NULL,
 doctor_name VARCHAR(60) DEFAULT '张医生', reported_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(patient_id) REFERENCES doctor_patient(id), INDEX idx_report_patient(patient_id,exam_date), INDEX idx_report_status(status)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS doctor_alert (
 id BIGINT PRIMARY KEY AUTO_INCREMENT, patient_id BIGINT NOT NULL, report_id BIGINT NOT NULL,
 type VARCHAR(30) NOT NULL, indicator VARCHAR(100) NOT NULL, resolved TINYINT DEFAULT 0,
 created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
 FOREIGN KEY(patient_id) REFERENCES doctor_patient(id), FOREIGN KEY(report_id) REFERENCES doctor_report(id)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;

